class EventEmitter {
  constructor() {
    this.events = new Map()
  }

  on(type, fn) {
    const handlers = this.events.get(type) || []
    handlers.push(fn)
    this.events.set(type, handlers)
    return this
  }

  emit(type, ...args) {
    const handlers = this.events.get(type) || []
    ;[...handlers].forEach(fn => fn(...args))
    return this
  }

  off(type, fn) {
    const handlers = this.events.get(type)
    if (!handlers) return this

    this.events.set(
      type,
      handlers.filter(handler => handler !== fn)
    )
    return this
  }
}

